let mut result: isize = operand[0];
for (i, op) in operator.iter().enumerate() {
    let next_operand = operand[i + 1];
    match op.as_str() {
        "+" => result = result + next_operand,
        "-" => result = result - next_operand,
        "*" => result = result * next_operand,
        "//" => result = (result / next_operand) as isize,
        "**" => result = (result.pow(next_operand as u32)) as isize,
        _ => panic!("Invalid operator"),
    }
}
result

